head.script:
// DOM 요소 조회(받은 id → mf_ 접두사 → G_ 뒤 접두사 → 접두사 제거). 2026-11
scwin.__getDom = function(id) {
	var P = 'mf_', d = function(k) { return document.getElementById(k); }, dd = function(k) { return k.replace(/(mf_){2,}/g, P); };
	var r = d(id); if (r) return r;
	var s = dd(P + id); r = d(s); if (r) return r;
	var g = s.indexOf('G_');
	if (g >= 0) { s = dd(s.slice(0, g + 2) + P + s.slice(g + 2)); r = d(s); if (r) return r; s = dd(P + s); r = d(s); if (r) return r; }
	return d(s.replace(P, ''));
};

scwin.test = function() {
	$w.log("main" + "_initScript");
};

scwin.post1 = function() {
	$w.log("main" + "_postScript1");
};

scwin.onpageload = function() {
	scwin.guid = 0;
};

scwin.trigger2_onclick = function() {
	scwin.guid++;
	var tabNm = "wframe",
		tabKey = "test_" + scwin.guid;
	var tabOptions = {
		label: tabNm,
		closable: true,
		openAction: "select"
	};
	var contentsOptions = {
		wframe: true,
		frameMode: "wframe",
		src: "/sample/common_link/wframe_spaInitCount_WPFF-138_(WSQ-3302)_sub.xml",
		scope: true
	};
	var ret = tabControl1.addTab(tabKey, tabOptions, contentsOptions);
	if (ret) {
		tabControl1.setSelectedTabIndex(tabControl1.getTabIndex(tabKey));
	}
};

scwin.trigger3_onclick = function() {
	var tabNm = "wframePreload",
		tabKey = "test_" + scwin.guid++;
	var tabOptions = {
		label: tabNm,
		closable: true,
		openAction: "select"
	};
	var contentsOptions = {
		frameMode: "wframePreload",
		src: "/sample/common_link/wframe_spaInitCount_WPFF-138_(WSQ-3302)_sub.xml",
		scope: true
	};
	var ret = tabControl1.addTab(tabKey, tabOptions, contentsOptions);
	if (ret) {
		tabControl1.setSelectedTabIndex(tabControl1.getTabIndex(tabKey));
	}
};

scwin.checkVal = function() {
	var temp = scwin.__getDom($p.id + 'tabControl1_contents_test_1_body').className.includes('w2wframe');
	return temp;
};
